{
    "name": "Creamy Indian Espresso",
    "description": "Indian Espresso Coffee made without an espresso machine.",
    "github": "aindrila2412",
    "ingredients": [
        {
            "quantity": "1",
            "measure": "teaspoon",
            "ingredient": "Instant Coffee Powder"
        },
        {
            "quantity": "2",
            "measure": "teaspoon",
            "ingredient": "Granulated Sugar"
        },
        {
            "quantity": "1",
            "measure": "cup",
            "ingredient": "milk"
        },
	{
            "quantity": "1",
            "measure": "teaspoon",
            "ingredient": "water"
        },
        {
            "quantity": "",
            "measure": "",
            "ingredient": "Cocoa Powder"
        }
    ],
    "directions": [
        "Put instant coffee powder and sugar in a coffee mug.",
        "Add 1 tsp. water and mix.",
        "Beat the mix vigorously with a spoon. You have to incorpotate as much air as you can. That will give you the whipped frothy coffee-sugar mix. The more you beat, the mix will become pale in colour. Make sure your mix is whipped and creamy enough.",
        "Heat a cup of milk and pour it over the whipped coffe-sugar paste. Stir. Sprinkle cocoa powder and serve immediately."
    ],
    "image": "creamy-indian-espresso.jpg",
    "keywords": [
        "coffee powder",
        "granulated sugar",
       	"milk",
	"water",
	"cocoa powder"
    ]
}

{
    "name": "Milo Dinosaur",
    "description": "Drink made of chocolate-malt, popular in Malaysia and Singapore.",
    "github": "pj",
    "ingredients": [
        {
            "quantity": "6",
            "measure": "tbsp",
            "ingredient": "Nestle Milo powder"
        },
        {
            "quantity": "100",
            "measure": "ml",
            "ingredient": "hot water"
        },
        {
            "quantity": "3/4",
            "measure": "tbsp",
            "ingredient": "condensed milk"
        },
        {
            "quantity": "a few",
            "measure": "cubes",
            "ingredient": "ice"
        },
        {
            "quantity": "3",
            "measure": "tbsp",
            "ingredient": "Nestle Milo powder to top it off"
        }
    ],
    "directions": [
        "Stir Milo and condensed milk with hot water in a tall glass until dissolved.",
        "Add ice cubes and stir lightly.",
        "Add ample amount of Milo to provide a crunchy top."
    ],
    "image": "milo-dinosaur.jpg",
    "keywords": [
        "ice",
        "chocolate",
        "non-alcoholic"
    ]
}

{
    "name": "Muskmelon Panaka",
    "description": "A tasy Ayurvedic summer cooler made using muskmelon,jaggery and green cardamom",
    "github": "Amit-Anveri",
    "ingredients": [
        {
            "quantity": "1",
            "measure": "cup",
            "ingredient": "Chopped muskmelon"
        },
        {
            "quantity": "2",
            "measure": "cup",
            "ingredient": "cold water"
        },
        {
            "quantity": "6",
            "measure": "tablespoon",
            "ingredient": "powdered jaggery"
        },
        {
            "quantity": "1",
            "measure": "pinch",
            "ingredient": "cardamom powder"
        },
        {
            "quantity": "2",
            "measure": "tablespoon",
            "ingredient": "lime juice"
        }
    ],
    "directions": [
        "In a blender add half of  the chopped muskmelon and the powdered jaggery",
        "Blend the mixture until it's completely mashed",
        "Add cold water, lime juice and cardamom powder",
        "Blend the mixture again till everything gets mixed",
        "Water and jaggery can be adjusted based on personal preference",
        "Strain the blended mixture into a jar and add the remaining half of chopped muskmelon",
        "Serve chilled"
    ],
    "image": "muskmelon-panaka.jpg",
    "keywords": [
        "Summer",
        "Ayurvedic",
        "chilled",
        "refreshing",
        "Non-alcoholic"
    ]
}

{
    "name": "Peppermint Shake",
    "description": "Peppermint Milkshakes - simple, quick and delicious! They're one of our favorite holiday treats! A cool drink made from vanilla ice cream, milk, peppermint extract and topped with whipped cream and crushed candy cane pieces!",
    "github": "iampk94",
    "ingredients": [
        {
            "quantity": "2",
            "measure": "cups",
            "ingredient": "Vanilla ice cream"
        },
        {
            "quantity": "1/2",
            "measure": "cup",
            "ingredient": "Milk"
        },
        {
            "quantity": "1/4",
            "measure": "cup",
            "ingredient": "Candy cane crushed"
        },
        {
            "quantity": "1",
            "measure": "tsp",
            "ingredient": "Peppermint extract"
        },
        {
            "quantity": "",
            "measure": "",
            "ingredient": "Whipped cream"
        }
    ],
    "directions": [
        "Add ice cream, milk, crushed cane pieces and peppermint extract to a blender.",
        "Mix until well combined.",
        "Pour into glass and top with whipped cream and candy cane pieces."
    ],
    "image": "peppermint-milkshake.jpg",
    "keywords": [
        "ice cream",
        "milkshake",
        "non-alcoholic",
        "vegan"
    ]
}

{
    "name": "Thai Tea with almond milk",
    "description": "Thai tea is popular in Asia. To make it more healthy by using almond milk and low sugar",
    "github": "miewliie",
    "ingredients": [
        {
            "quantity": "2",
            "measure": "teaspoon",
            "ingredient": "Thai tea"
        },
        {
            "quantity": "1",
            "measure": "cup",
            "ingredient": "Boiling water"
        },
        {
            "quantity": "1",
            "measure": "teaspoon",
            "ingredient": "Sugar"
        },
        {
            "quantity": "1",
            "measure": "teaspoon",
            "ingredient": "Sweetened condensed milk"
        },
        {
            "quantity": "3/4",
            "measure": "cup",
            "ingredient": "Almond milk"
        },
        {
            "quantity": "1",
            "measure": "cup",
            "ingredient": "Crushed ice"
        }
    ],
    "directions": [
        "1. Take your tea sock and add thai tea. Put tea sock on boil water cup. To steep the tea.",
        "2. Leave the tea sock for a couple minutes to extract the tea flavour.",
        "3. Pour the tea to a cup. Mix all the the rest of ingredients except ice.",
        "4. Bring the cup with the ice. Pour the tea to this cup."
    ],
    "image": "thai-tea-with-almond-milk.jpg",
    "keywords": [
        "thai tea",
        "almond milk"
    ]
}

{
    "name": "Ginger Mint Tea",
    "description": "A soothing hot drink for cold; but also for relaxation and digestion",
    "github": "jacksonisaac",
    "ingredients": [
        {
            "quantity": "1",
            "measure": "piece",
            "ingredient": "fresh ginger"
        },
        {
            "quantity": "5",
            "measure": "sprigs",
            "ingredient": "Mint"
        },
        {
            "quantity": "1",
            "measure": "cup",
            "ingredient": "boiled water"
        }
    ],
    "directions": [
        "Finely slice the ginger into thin rounds/strips",
        "Strip the stems of the fresh mint",
        "In a saucepan or a water boiler, bring 1 cup of water to boil",
        "Pour the water into a cup, steep in the finely sliced ginger and sprigs of mint for 3-5 minutes"
    ],
    "image": "ginger-mint-tea.jpg",
    "keywords": [
        "tea",
        "vegan",
        "healthy"
    ]
}

